package com.fasterxml.jackson.dataformat.xml.ser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.IOContext;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.ObjectCodec;
import com.fasterxml.jackson.core.base.GeneratorBase;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.dataformat.xml.XmlPrettyPrinter;
import com.fasterxml.jackson.dataformat.xml.ser.ToXmlGenerator;
import com.fasterxml.jackson.dataformat.xml.util.DefaultXmlPrettyPrinter;
import com.fasterxml.jackson.dataformat.xml.util.StaxUtil;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import javax.xml.namespace.QName;
import javax.xml.stream.XMLStreamException;
import javax.xml.stream.XMLStreamWriter;
import org.codehaus.stax2.XMLStreamWriter2;
import org.codehaus.stax2.ri.Stax2WriterAdapter;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.isNull;
import static org.mockito.Mockito.*;

public class ToXmlGenerator_writeBoolean_TriageGen0Test {

    private IOContext ioContext;
    private ObjectCodec codec;
    private XMLStreamWriter xmlStreamWriter;
    private ToXmlGenerator generator;
    private QName testQName;

    @Before
    public void setUp() {
        ioContext = mock(IOContext.class);
        codec = mock(ObjectCodec.class);
        xmlStreamWriter = mock(XMLStreamWriter.class);
        testQName = new QName("http://test.com", "testElement");

        // We spy on the generator to control protected methods like checkNextIsUnwrapped and handleMissingName
        generator = spy(new ToXmlGenerator(ioContext, 0, 0, codec, xmlStreamWriter));
    }

    /**
     * Tests the branch where _nextName is null.
     * Note: Since handleMissingName is protected, we verify it is called.
     */
    @Test
    public void testWriteBoolean_MissingName() throws Exception {
        generator.setNextName(null);

        // We need to prevent handleMissingName from throwing an exception if we want to test further,
        // but in real code it likely throws an exception. Here we just ensure the path is hit.
        doNothing().when(generator).handleMissingName();

        // To avoid NullPointerException in the logic after handleMissingName, 
        // we must mock the behavior such that the code doesn't crash before we can verify.
        // However, the code uses _nextName.getNamespaceURI(). So if _nextName is null, it will crash.
        // We test that the call to handleMissingName occurs.
        try {
            generator.writeBoolean(true);
        } catch (NullPointerException e) {
            // Expected because _nextName is null and used immediately after handleMissingName
        }

        verify(generator).handleMissingName();
    }

    /**
     * Tests the branch where _nextIsAttribute is true.
     */
    @Test
    public void testWriteBoolean_IsAttribute() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(true);

        generator.writeBoolean(true);

        verify(xmlStreamWriter).writeBooleanAttribute(isNull(), eq("http://test.com"), eq("testElement"), eq(true));
    }

    /**
     * Tests the branch where checkNextIsUnwrapped() is true.
     */
    @Test
    public void testWriteBoolean_IsUnwrapped() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        doReturn(true).when(generator).checkNextIsUnwrapped();

        generator.writeBoolean(false);

        verify(xmlStreamWriter).writeBoolean(false);
        verify(xmlStreamWriter, never()).writeStartElement(any(), any());
    }

    /**
     * Tests the branch where _xmlPrettyPrinter is NOT null (Leaf Element path).
     */
    @Test
    public void testWriteBoolean_WithPrettyPrinter() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        doReturn(false).when(generator).checkNextIsUnwrapped();

        PrettyPrinter mockPrettyPrinter = mock(PrettyPrinter.class);
        generator.setPrettyPrinter(mockPrettyPrinter);

        generator.writeBoolean(true);

        verify(mockPrettyPrinter).writeLeafElement(eq(xmlStreamWriter), eq("http://test.com"), eq("testElement"), eq(true));
        verify(xmlStreamWriter, never()).writeStartElement(any(), any());
    }

    /**
     * Tests the branch where _xmlPrettyPrinter is null (Standard Element path).
     */
    @Test
    public void testWriteBoolean_NoPrettyPrinter() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        doReturn(false).when(generator).checkNextIsUnwrapped();

        // Ensure pretty printer is null
        generator.setPrettyPrinter(null);

        generator.writeBoolean(true);

        verify(xmlStreamWriter).writeStartElement("http://test.com", "testElement");
        verify(xmlStreamWriter).writeBoolean(true);
        verify(xmlStreamWriter).writeEndElement();
    }

    /**
     * Tests the exception handling branch when XMLStreamException is thrown.
     */
    @Test(expected = RuntimeException.class) 
    public void testWriteBoolean_ThrowsXmlStreamException() throws Exception {
        generator.setNextName(testQName);
        generator.setNextIsAttribute(false);
        doReturn(false).when(generator).checkNextIsUnwrapped();

        // Force an exception in the writer
        doThrow(new XMLStreamException("Simulated error")).when(xmlStreamWriter).writeBoolean(anyBoolean());

        try {
            generator.writeBoolean(true);
        } catch (Exception e) {
            // The code catches XMLStreamException and throws a GenerationException (which is a RuntimeException)
            throw e;
        }
    }
}
